// Agrega pedidos do dia e monta mensagem WhatsApp
const orders = $('Pedidos do dia').first().json || [];
const settings = ($('Config da empresa').first().json || [])[0] || {};

if (!settings.recebe_resumo_diario) {
  return [{ json: { skip: true, reason: 'recebe_resumo_diario = false' } }];
}
if (!settings.whatsapp_phone) {
  return [{ json: { skip: true, reason: 'whatsapp_phone não configurado' } }];
}

const byStatus = orders.reduce((acc, o) => { acc[o.status] = (acc[o.status] || 0) + 1; return acc; }, {});
const faturamento = orders
  .filter(o => !['recusado', 'cancelado'].includes(o.status))
  .reduce((sum, o) => sum + Number(o.valor_total || 0), 0);
const pendentes = orders.filter(o => o.status === 'pendente_aprovacao').length;
const aguardandoFabrica = orders.filter(o => o.status === 'aguardando_fabrica').length;

const fmt = (n) => new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(n);
const hoje = new Date().toLocaleDateString('pt-BR');

const lines = [
  `📊 *Resumo Poxpur — ${hoje}*`,
  '',
  `Pedidos hoje: *${orders.length}*`,
  `Faturamento: *${fmt(faturamento)}*`,
  '',
  '*Por status:*',
  ...Object.entries(byStatus).map(([s, c]) => `• ${s.replace(/_/g, ' ')}: ${c}`),
];

if (pendentes > 0) {
  lines.push('', `⚠️ *${pendentes} pedido(s) aguardando sua aprovação*`);
}
if (aguardandoFabrica > 0) {
  lines.push(`🏭 *${aguardandoFabrica} pedido(s) aguardando fábrica (sem estoque)*`);
}

lines.push('', '_Acesse o Sales Hub pra ver detalhes._');

return [{
  json: {
    skip: false,
    phone: settings.whatsapp_phone.replace(/^\+/, ''),
    text: lines.join('\n')
  }
}];
